from pathlib import Path
p=Path(__file__).resolve().parents[1]/'frontend/src/features/admissions/components/AdmissionAdminWorkbench.tsx'
t=p.read_text(encoding='utf-8')
needle='<h3 className="mb-3 text-sm font-bold">Informations à rapprocher</h3>'
t=t.replace(needle,needle+'''{extracted && <div className="mb-4 rounded-lg border border-blue-200 p-3"><h4 className="text-sm font-bold">Propositions OCR de cette version</h4><p className="mt-1 text-xs text-slate-500">Vérifiez sur la pièce. Une proposition ne vaut pas conformité.</p>{Object.entries(extracted.fields ?? {}).map(([key, field]) => <div className="mt-3 text-sm" key={key}><p className={field.conflict ? 'text-red-700' : ''}>{key} : {String(field.value)}{field.conflict && ' · Conflit à examiner'}</p>{!['cin', 'cne'].includes(key) && app.dossier_status !== 'approved' && <button className="min-h-11 text-xs text-blue-700 underline" onClick={() => { const map: Record<string, string> = { first_name_fr: 'first_name', last_name_fr: 'last_name', bac_type: 'bac_series' }; setCorrections(c => ({ ...c, [map[key] || key]: field.value })) }}>Reporter après vérification</button>}</div>)}{Object.entries(corrections).map(([key, value]) => <label className="mt-2 block text-xs" key={key}>Correction : {key}<input className={`${input} mt-1`} value={value} onChange={e => setCorrections(c => ({ ...c, [key]: e.target.value }))}/></label>)}{Object.keys(corrections).length > 0 && <p className="mt-2 text-xs text-amber-800">Les corrections seront enregistrées avec votre observation lors de la vérification de cette version.</p>}</div>}''')
p.write_text(t,encoding='utf-8')
